    connector_about: { hint: "TOPIC LINKER (" + thai + "): links subject to topic. [noun]" + thai + "[topic]. Example: \u0E2B\u0E19\u0E31\u0E07\u0E2A\u0E37\u0E2D\u0E40\u0E25\u0E48\u0E21\u0E19\u0E35\u0E49" + thai + "\u0E01\u0E32\u0E23\u0E40\u0E14\u0E34\u0E19\u0E17\u0E32\u0E07\u0E04\u0E23\u0E31\u0E1A. NEVER as standalone object." },
    connector_because: { hint: "CAUSE CONNECTOR (" + thai + "): joins two clauses. [clause1]" + thai + "[clause2]. Example: \u0E1C\u0E21\u0E44\u0E21\u0E48\u0E44\u0E1B" + thai + "\u0E23\u0E16\u0E15\u0E34\u0E14\u0E04\u0E23\u0E31\u0E1A. TWO clauses required." },
    connector_but: { hint: "CONTRAST (" + thai + "): contrasts two ideas. [clause1]" + thai + "[clause2]. Example: \u0E2D\u0E22\u0E32\u0E01\u0E44\u0E1B" + thai + "\u0E44\u0E21\u0E48\u0E27\u0E48\u0E32\u0E07\u0E04\u0E23\u0E31\u0E1A." },
    connector_if: { hint: "CONDITION (" + thai + "): starts condition clause. " + thai + "+[condition]+[result]. Example: " + thai + "\u0E27\u0E48\u0E32\u0E07\u0E44\u0E1B\u0E14\u0E49\u0E27\u0E22\u0E01\u0E31\u0E19\u0E44\u0E2B\u0E21\u0E04\u0E23\u0E31\u0E1A." },
