    meal: { hint: "MEAL WORD (" + thai + "): \u0E01\u0E34\u0E19/\u0E2A\u0E31\u0E48\u0E07/\u0E2B\u0E23\u0E37\u0E2D\u0E22\u0E31\u0E07. \u0E01\u0E34\u0E19" + thai + "\u0E41\u0E25\u0E49\u0E27\u0E2B\u0E23\u0E37\u0E2D\u0E22\u0E31\u0E07\u0E04\u0E30, \u0E1C\u0E21\u0E08\u0E30\u0E44\u0E1B\u0E01\u0E34\u0E19" + thai + "\u0E04\u0E23\u0E31\u0E1A. NEVER: \u0E44\u0E1B" + thai + " without \u0E01\u0E34\u0E19, \u0E40\u0E2B\u0E47\u0E19" + thai + "." },
    colour: { hint: "COLOUR (" + thai + "): describe objects or state preference. [noun]+" + thai + "\u0E04\u0E23\u0E31\u0E1A, \u0E0A\u0E2D\u0E1A" + thai + "\u0E04\u0E23\u0E31\u0E1A. NEVER: \u0E40\u0E2B\u0E47\u0E19" + thai + " without naming an object." },
    study_material: { hint: "STUDY MATERIAL (" + thai + "): use \u0E17\u0E33/\u0E2D\u0E48\u0E32\u0E19/\u0E40\u0E02\u0E35\u0E22\u0E19\u0E43\u0E19/\u0E2A\u0E48\u0E07. \u0E17\u0E33" + thai + "\u0E04\u0E23\u0E31\u0E1A, \u0E2A\u0E48\u0E07" + thai + "\u0E41\u0E25\u0E49\u0E27\u0E2B\u0E23\u0E37\u0E2D\u0E22\u0E31\u0E07\u0E04\u0E30. NEVER: \u0E40\u0E02\u0E35\u0E22\u0E19" + thai + " (say \u0E40\u0E02\u0E35\u0E22\u0E19\u0E43\u0E19" + thai + "), \u0E40\u0E2B\u0E47\u0E19" + thai + "." },
    place: { hint: "PLACE (" + thai + "): use location/movement. " + thai + "\u0E2D\u0E22\u0E39\u0E48\u0E17\u0E35\u0E48\u0E44\u0E2B\u0E19\u0E04\u0E23\u0E31\u0E1A, \u0E2D\u0E22\u0E39\u0E48\u0E43\u0E01\u0E25\u0E49" + thai + "\u0E44\u0E2B\u0E21\u0E04\u0E30, \u0E1C\u0E21\u0E44\u0E1B\u0E17\u0E35\u0E48" + thai + "\u0E41\u0E25\u0E49\u0E27\u0E04\u0E23\u0E31\u0E1A. Use \u0E17\u0E35\u0E48 with \u0E44\u0E1B." },
    adjective: { hint: "ADJECTIVE (" + thai + "): must describe a subject. [subject]+" + thai + "\u0E04\u0E23\u0E31\u0E1A, [noun]\u0E19\u0E35\u0E49" + thai + "\u0E04\u0E23\u0E31\u0E1A. NEVER: \u0E40\u0E2B\u0E47\u0E19" + thai + ", \u0E21\u0E35" + thai + " as object. No subject = no sentence." },
