    { prompt: "Say it is not that spicy", thai: "\u0E44\u0E21\u0E48\u0E40\u0E1C\u0E47\u0E14\u0E02\u0E19\u0E32\u0E14\u0E19\u0E31\u0E49\u0E19\u0E04\u0E23\u0E31\u0E1A", english: "It is not that spicy.", phonetic: "m\xE2i ph\xE8t kh\xE0-n\xE0at-n\xE1n khr\xE2p", words: [{ p: "m\xE2i", e: "not" }, { p: "ph\xE8t", e: "spicy" }, { p: "kh\xE0-n\xE0at-n\xE1n", e: "that much" }, { p: "khr\xE2p", e: "[polite]" }], target_phonetic: "kh\xE0-n\xE0at-n\xE1n" },
    { prompt: "Ask if it is really that urgent", thai: "\u0E15\u0E49\u0E2D\u0E07\u0E23\u0E35\u0E1A\u0E02\u0E19\u0E32\u0E14\u0E19\u0E31\u0E49\u0E19\u0E44\u0E2B\u0E21\u0E04\u0E30", english: "Is it really that urgent?", phonetic: "t\xF4ng r\xEEip kh\xE0-n\xE0at-n\xE1n m\u01CEi kh\xE1", words: [{ p: "t\xF4ng", e: "must" }, { p: "r\xEEip", e: "hurry" }, { p: "kh\xE0-n\xE0at-n\xE1n", e: "that much" }, { p: "m\u01CEi", e: "?" }, { p: "kh\xE1", e: "[polite]" }], target_phonetic: "kh\xE0-n\xE0at-n\xE1n" }
