    { prompt: "Say it looks like a hotel", thai: "\u0E21\u0E31\u0E19\u0E40\u0E2B\u0E21\u0E37\u0E2D\u0E19\u0E42\u0E23\u0E07\u0E41\u0E23\u0E21\u0E04\u0E23\u0E31\u0E1A", english: "It looks like a hotel.", phonetic: "man m\u01D4ean roong-raem khr\xE2p", words: [{ p: "man", e: "it" }, { p: "m\u01D4ean", e: "looks like" }, { p: "roong-raem", e: "hotel" }, { p: "khr\xE2p", e: "[polite]" }], target_phonetic: "m\u01D4ean" },
    { prompt: "Say you feel the same way", thai: "\u0E1C\u0E21\u0E23\u0E39\u0E49\u0E2A\u0E36\u0E01\u0E40\u0E2B\u0E21\u0E37\u0E2D\u0E19\u0E01\u0E31\u0E19\u0E04\u0E23\u0E31\u0E1A", english: "I feel the same way.", phonetic: "ph\u01D2m r\xFAu-s\xF9ek m\u01D4ean-gan khr\xE2p", words: [{ p: "ph\u01D2m", e: "I" }, { p: "r\xFAu-s\xF9ek", e: "feel" }, { p: "m\u01D4ean-gan", e: "same" }, { p: "khr\xE2p", e: "[polite]" }], target_phonetic: "m\u01D4ean" }
