    { prompt: "Say today's journey was tiring", thai: "\u0E01\u0E32\u0E23\u0E40\u0E14\u0E34\u0E19\u0E17\u0E32\u0E07\u0E27\u0E31\u0E19\u0E19\u0E35\u0E49\u0E40\u0E2B\u0E19\u0E37\u0E48\u0E2D\u0E22\u0E04\u0E23\u0E31\u0E1A", english: "Today's journey was tiring.", phonetic: "gaan-d\u0259\u0259n-thaang wan-n\xEDi n\xF9eai khr\xE2p", words: [{ p: "gaan-d\u0259\u0259n-thaang", e: "journey" }, { p: "wan-n\xEDi", e: "today" }, { p: "n\xF9eai", e: "tiring" }, { p: "khr\xE2p", e: "[polite]" }], target_phonetic: "gaan-d\u0259\u0259n-thaang" }
